<script lang="ts">import{InlineOverflow,type InlineOverflowItem}from'./inline-overflow';import{TickRail,type TickRailItem}from'./tick-rail';import{Transform}from'./transform';import{AskAiButton}from'./ask-ai-button';import{ButtonGroup}from'./button-group';import{Button}from'./button';import{SplitButton}from'./split-button';let{mode='tick',disabled=false}:{mode?:string;disabled?:boolean}=$props();let value=$state(0),show=$state(false),actions=$state(0);const overflowItems:InlineOverflowItem[]=[{label:'First'},{label:'Second'},{label:'Third'}];const railItems:TickRailItem[]=[{label:'First',detail:'One'},{label:'Second',detail:'Two'},{label:'Third',detail:'Three'}]</script>
{#if mode==='overflow'}<InlineOverflow items={overflowItems}/>{:else if mode==='tick'}<TickRail items={railItems} bind:active={value}/><output>{value}</output>{:else if mode==='transform'}<Transform {show} keepMounted><button>Inside</button></Transform>{:else if mode==='ai'}<AskAiButton label="Ask" loading={disabled}/>{:else if mode==='group'}<ButtonGroup orientation="vertical"><Button aria-label="A">{#snippet children()}A{/snippet}</Button><Button aria-label="B">{#snippet children()}B{/snippet}</Button></ButtonGroup>{:else}<SplitButton label="Save" {disabled} items={['Draft']} onclick={()=>actions++}>{#snippet menu()}<span></span>{/snippet}</SplitButton><output>{actions}</output>{/if}
